select id, 'CLOCK TOWER|THE CLOCK TOWER|INSIDE THE CLOCK TOWER', '["Run `cat scroll_1.txt | base64 -d | caesar-bruteforce` and find the readable line. It gives you a key.", "Scroll I says the Vigenère key is WHISKERS. Run `vigenere-decrypt WHISKERS $SCROLL_2`.", "Scroll II says a = 7 and b = 10. Run `affine-decrypt 7 10 $SCROLL_3`."]'::jsonb from public.labs where slug = 'great-decryption'
