-- Lab 1: Caesar's Scroll
insert into public.labs (storyline_id, slug, title, description, story_segment, challenge_prompt, cipher_type, payload, skills, is_boss, order_index, xp_reward)
select s.id, 'caesars-scroll', 'Caesar''s Scroll', 'Read a warning from ancient Rome, written in Caesar''s own cipher.', 'Rome, 15 March 44 BC. A slave hurries through the Forum with a scroll for Julius Caesar. In our timeline Caesar never read it. The Paradox Cat has now erased the scroll from the archives altogether. Decrypt it so history remembers the warning, and the name inside.', 'The historian Suetonius tells us which shift Caesar used. Decrypt the scroll and submit the name of the conspirators'' leader.', 'caesar',
  '{"intro": [{"speaker": "Archivist Tabby", "text": "Welcome to the Archive Division, recruit. I''m Tabby, and I look after history''s secrets."}, {"speaker": "Archivist Tabby", "text": "Someone calling themselves the Paradox Cat is stealing famous decryptions out of the timeline."}, {"speaker": "you", "text": "Stealing them? Why?"}, {"speaker": "Archivist Tabby", "text": "If nobody ever cracks these messages, nobody learns from them, and cryptography never evolves. We''re going to crack them all again, in order."}, {"speaker": "Archivist Tabby", "text": "First stop is Rome. Julius Caesar had his own cipher, and we know his key because a historian wrote it down."}], "concept": {"title": "The original Caesar cipher", "body": "Around AD 120, Suetonius wrote that Caesar \"substituted the fourth letter of the alphabet, namely D, for A, and so with the others\", which is a shift of 3. Caesar''s security came from his enemies not knowing the method at all. Today we assume the attacker knows the algorithm (Kerckhoffs''s principle), and with only 25 keys, that makes a Caesar cipher trivial to break."}, "files": {"scroll.txt": "EHZDUH WKH LGHV RI PDUFK. WKH VHQDWRUV ZLOO VWULNH DW WKH WKHDWUH RI SRPSHB. WKHLU OHDGHU LV EUXWXV."}, "given": {"Historian": "Suetonius, Life of Julius Caesar §56"}, "tools": ["cat scroll.txt", "caesar-decrypt 3 $SCROLL", "caesar-bruteforce $SCROLL"], "outro": "BRUTUS. The scroll is back in the archive. Next stop: 1941, and a machine with 158 quintillion settings."}'::jsonb,
  array['Historical Cryptography', 'Classical Ciphers']::text[], false, 1, 100
from public.storylines s where s.slug = 'puzzles-of-the-past'
on conflict (slug) do update set
  storyline_id = excluded.storyline_id, title = excluded.title, description = excluded.description,
  story_segment = excluded.story_segment, challenge_prompt = excluded.challenge_prompt,
  cipher_type = excluded.cipher_type, payload = excluded.payload, skills = excluded.skills,
  is_boss = excluded.is_boss, order_index = excluded.order_index, xp_reward = excluded.xp_reward;

