select id, 'BRUTUS|MARCUS BRUTUS|MARCUS JUNIUS BRUTUS', '["\"D for A\" means each letter moved 3 places forward. To decrypt, shift back by 3.", "Run `caesar-decrypt 3 $SCROLL`.", "The last sentence names the leader: BRUTUS."]'::jsonb from public.labs where slug = 'caesars-scroll'
on conflict (lab_id) do update set solution = excluded.solution, hints = excluded.hints;

-- Lab 2: Enigma Enigma
insert into public.labs (storyline_id, slug, title, description, story_segment, challenge_prompt, cipher_type, payload, skills, is_boss, order_index, xp_reward)
select s.id, 'enigma-enigma', 'Enigma Enigma', 'Break an Enigma message by exploiting a lazy operator''s key choice.', 'Bletchley Park, 1941. Hut 8 has intercepted a U-boat weather report. A captured codebook gave you the rotor order, but not today''s start position. The Paradox Cat wants this message to stay unread. Luckily, this operator is known for picking lazy settings.', 'Find the operator''s start position, decrypt the intercept with the `enigma` command, and submit the place where the U-boat wolfpack is gathering.', 'enigma',
  '{"intro": [{"speaker": "Archivist Tabby", "text": "Enigma: three spinning rotors, a reflector, and a new substitution alphabet for every single keypress."}, {"speaker": "you", "text": "Then how did anyone break it?"}, {"speaker": "Archivist Tabby", "text": "Mathematics, the Bombe machines, and people. Operators were tired and lazy. They picked start positions like AAA, or letters next to each other on the keyboard."}, {"speaker": "Archivist Tabby", "text": "Bletchley Park called those \"cillies\". Guess this operator''s cilly and the machine does the rest."}], "concept": {"title": "Rotor machines & human error", "body": "Each keypress steps the right rotor; at its notch it carries the middle rotor along, like an odometer. Electricity passes through the three rotors, bounces off the reflector and comes back through them, so encryption is its own inverse: type the ciphertext with the same settings and out comes the plaintext. The reflector also means a letter can never encrypt to itself. Polish and British cryptanalysts exploited this, along with predictable \"cribs\" such as WETTER (weather) and lazy operator keys."}, "files": {"intercept.txt": "HGIXF HTZAJ YNWVE GARBW EDKNT PFDZQ OTRJE WTSWH HRMIF UAPXH IQMOE IHBPM SFIUY"}, "given": {"Rotors (left→right)": "I-II-III", "Reflector": "B", "Ring settings": "AAA", "Start position": "unknown (lazy operator)"}, "tools": ["enigma I-II-III AAA $INTERCEPT", "enigma I-II-III <start> $INTERCEPT"], "outro": "ICELAND. The convoys are rerouted around the wolfpack. Next stop: the Pacific, 1945, and a code that was never broken."}'::jsonb,
  array['Historical Cryptography', 'Machine Ciphers', 'Cryptanalysis']::text[], false, 2, 150
from public.storylines s where s.slug = 'puzzles-of-the-past'
on conflict (slug) do update set
  storyline_id = excluded.storyline_id, title = excluded.title, description = excluded.description,
  story_segment = excluded.story_segment, challenge_prompt = excluded.challenge_prompt,
  cipher_type = excluded.cipher_type, payload = excluded.payload, skills = excluded.skills,
  is_boss = excluded.is_boss, order_index = excluded.order_index, xp_reward = excluded.xp_reward;

insert into public.lab_solutions (lab_id, solution, hints)
select id, 'ICELAND|NEAR ICELAND', '["Try the laziest settings first: `enigma I-II-III AAA $INTERCEPT`, then ABC, then XYZ… Readable output means you''ve found it.", "Look at the top-left row of a keyboard. Operators often just typed three keys next to each other.", "The start position is QWE. Run `enigma I-II-III QWE $INTERCEPT`. The X characters separate words."]'::jsonb from public.labs where slug = 'enigma-enigma'
on conflict (lab_id) do update set solution = excluded.solution, hints = excluded.hints;

-- Lab 3: The Navajo Net
insert into public.labs (storyline_id, slug, title, description, story_segment, challenge_prompt, cipher_type, payload, skills, is_boss, order_index, xp_reward)
select s.id, 'navajo-net', 'The Navajo Net', 'Decode a WW2 transmission sent by Navajo code talkers.', 'Iwo Jima, February 1945. Navajo code talkers sent battlefield messages that the enemy never managed to break. The Paradox Cat has scrambled the archive copy of one famous transmission. Use the codebook to rebuild the sentence word by word.', 'Translate the transmission with the codebook (each code word is one letter, or a whole military term). Submit the name of the mountain where the flag was raised.', 'code',
  '{"intro": [{"speaker": "Archivist Tabby", "text": "This one isn''t a cipher at all. It''s a code."}, {"speaker": "you", "text": "What''s the difference?"}, {"speaker": "Archivist Tabby", "text": "A cipher scrambles letters with an algorithm and a key. A code replaces whole words or ideas using a codebook."}, {"speaker": "Archivist Tabby", "text": "The Navajo code talkers built theirs on top of the Navajo language, which was unwritten and almost unknown outside the Navajo Nation. It was never broken."}], "concept": {"title": "Codes vs ciphers: the Navajo code talkers", "body": "Starting in 1942, around 400 Navajo Marines served as code talkers. They used about 200 (later over 600) code terms. Military words became Navajo words: a submarine was BESH-LO (\"iron fish\") and a fighter plane was DA-HE-TIH-HI (\"hummingbird\"). Other words were spelled out using a Navajo word for each letter, such as WOL-LA-CHEE (ant) for A. They could encode, transmit and decode a message in seconds, far faster than cipher machines. This lab uses a simplified one-word-per-letter alphabet. The real code had several words for common letters, to defeat frequency analysis."}, "files": {"transmission.txt": "DA-HE-TIH-HI / MOASI NE-AHS-JAH A-KEH-DI-GLINI DZEH GAH / GAH DZEH CA-YEILTH NO-DA-IH DZEH DIBEH THAN-ZIE DZEH BE / MA-E DIBEH-YAZZIE WOL-LA-CHEE KLIZZIE / GAH WOL-LA-CHEE TKIN DIBEH DZEH BE / NE-AHS-JAH NESH-CHEE / DIBEH NO-DA-IH GAH TKIN SHUSH WOL-LA-CHEE MOASI LIN TKIN"}, "tools": ["codebook", "codebook <code word>", "cat transmission.txt | codebook"], "outro": "SURIBACHI. The flag raising on Mount Suribachi was reported by the code talkers. Next stop: the Cold War, and a cipher that''s mathematically unbreakable, unless someone cuts corners."}'::jsonb,
  array['Historical Cryptography', 'Codes & Codebooks']::text[], false, 3, 100
from public.storylines s where s.slug = 'puzzles-of-the-past'
on conflict (slug) do update set
  storyline_id = excluded.storyline_id, title = excluded.title, description = excluded.description,
  story_segment = excluded.story_segment, challenge_prompt = excluded.challenge_prompt,
  cipher_type = excluded.cipher_type, payload = excluded.payload, skills = excluded.skills,
  is_boss = excluded.is_boss, order_index = excluded.order_index, xp_reward = excluded.xp_reward;

insert into public.lab_solutions (lab_id, solution, hints)
select id, 'SURIBACHI|MOUNT SURIBACHI|MT SURIBACHI', '["Run `codebook` to see the alphabet. Each code word is one letter, and `/` separates words.", "You can translate the whole file at once: `cat transmission.txt | codebook`.", "The last word is spelled DIBEH NO-DA-IH GAH TKIN SHUSH WOL-LA-CHEE MOASI LIN TKIN, which is SURIBACHI."]'::jsonb from public.labs where slug = 'navajo-net'
on conflict (lab_id) do update set solution = excluded.solution, hints = excluded.hints;

-- Lab 4: Cold War Crack
insert into public.labs (storyline_id, slug, title, description, story_segment, challenge_prompt, cipher_type, payload, skills, is_boss, order_index, xp_reward)
select s.id, 'cold-war-crack', 'Cold War Crack', 'Break a one-time pad that was used twice.', 'Arlington Hall, 1946. Two Soviet cables were encrypted with a one-time pad, which should be impossible to break. But wartime shortages meant pad pages were sometimes reused. Both cables were sent with the same page. The Paradox Cat wants the VENONA project never to find this.', 'Cable A begins with the standard header. Use it to recover part of the pad, decrypt the start of cable B with it, and submit the mole''s codename.', 'otp',
  '{"intro": [{"speaker": "Archivist Tabby", "text": "A one-time pad is the only cipher that''s mathematically proven unbreakable."}, {"speaker": "you", "text": "So we''re stuck?"}, {"speaker": "Archivist Tabby", "text": "Only if it''s used correctly: a truly random key, as long as the message, used exactly once. These two cables share one key."}, {"speaker": "Archivist Tabby", "text": "And every cable from this station starts with the same header. Know the plaintext and you know the key at those positions."}], "concept": {"title": "One-time pads & key reuse", "body": "With letters as numbers, c = p + k (mod 26), where the key k is random and as long as the message. Every plaintext is equally likely, so the ciphertext reveals nothing. Reuse breaks that. If you know any plaintext p, then k = c − p (mod 26) at those positions, and the same k decrypts the second message. The real VENONA project used pad reuse to read thousands of Soviet cables and expose spies."}, "files": {"cable_a.txt": "PKLOA YNAPI KOYKS YAJPN ABNKI SWODE JCPKJ OPWPE KJPDA LWYGW CAWNN ERAOB NEZWU", "cable_b.txt": "QNCAJ PPDAI KHAOY KZAJW IAEOJ ECDPE JCWHA ZKJKP YKJPW YPDEI ZENAY PHUOP KLTTT"}, "given": {"Standard header (cable A)": "TOP SECRET MOSCOW CENTRE FROM WASHINGTON STATION"}, "tools": ["otp-key \"<known plaintext>\" $CABLE_A", "otp-decrypt <key> $CABLE_B"], "outro": "NIGHTINGALE. The mole is exposed. One last stop: 1977, when three researchers changed secrecy forever."}'::jsonb,
  array['Historical Cryptography', 'Cryptanalysis', 'Symmetric Cryptography']::text[], false, 4, 200
from public.storylines s where s.slug = 'puzzles-of-the-past'
on conflict (slug) do update set
  storyline_id = excluded.storyline_id, title = excluded.title, description = excluded.description,
  story_segment = excluded.story_segment, challenge_prompt = excluded.challenge_prompt,
  cipher_type = excluded.cipher_type, payload = excluded.payload, skills = excluded.skills,
  is_boss = excluded.is_boss, order_index = excluded.order_index, xp_reward = excluded.xp_reward;

insert into public.lab_solutions (lab_id, solution, hints)
select id, 'NIGHTINGALE', '["Recover the pad from the header: `otp-key \"TOP SECRET MOSCOW CENTRE FROM WASHINGTON STATION\" $CABLE_A`.", "Feed that key into cable B: `otp-decrypt <key from step 1> $CABLE_B`. Positions the key doesn''t cover show as ?.", "Cable B starts with URGENT THE MOLES CODENAME IS NIGHTINGALE."]'::jsonb from public.labs where slug = 'cold-war-crack'
on conflict (lab_id) do update set solution = excluded.solution, hints = excluded.hints;

-- Lab 5: Digital Age Decryption
insert into public.labs (storyline_id, slug, title, description, story_segment, challenge_prompt, cipher_type, payload, skills, is_boss, order_index, xp_reward)
select s.id, 'digital-age-decryption', 'Digital Age Decryption', 'Boss lab: break small RSA to recover a session key, then decrypt the final message.', '1977: Rivest, Shamir and Adleman publish RSA, and anyone can now encrypt to you without ever sharing a secret. The Paradox Cat''s final message uses hybrid encryption, just like the web does today. The session key is locked with RSA, but the RSA key is far too small.', 'Factor n, compute the private key d, RSA-decrypt the session key, then use it to decrypt the message (Vigenère). Submit the final word.', 'rsa',
  '{"intro": [{"speaker": "Archivist Tabby", "text": "Every cipher we''ve seen so far had the same weakness: both sides needed to share a secret key first."}, {"speaker": "Archivist Tabby", "text": "Public-key cryptography fixed that. Anyone can lock a message with your public key, and only your private key opens it."}, {"speaker": "you", "text": "And this one is breakable because…?"}, {"speaker": "Archivist Tabby", "text": "Its n is tiny. Factor n and you can rebuild the private key. Then it''s 2,000 years of cryptography in one lab. Go restore the timeline!"}], "concept": {"title": "RSA & hybrid encryption", "body": "Pick primes p, q. Public key: n = p·q and e. Private key: d = e⁻¹ mod φ(n), where φ(n) = (p−1)(q−1). Encrypt c = mᵉ mod n; decrypt m = cᵈ mod n. Security rests on factoring n being hard, and real keys are 2048+ bits. Because RSA is slow, real systems (TLS, PGP) use it only to send a short random session key, and encrypt the actual data with a fast symmetric cipher. That''s hybrid encryption. Here each letter of the session key (A=1 … Z=26) was encrypted separately."}, "files": {"public_key.txt": "n = 3233\ne = 17", "session_key.txt": "3023 1188 2100 1972 2549 2369", "message.txt": "VIEOEGMOCIGOHHJ BVSX NIIIKEFVZ. SXHG TIRYTL KW EYT YMMEE VCGPRX YYCT GU T WCMIKK GZVQ. ZAY KQZKECEM VY KYJBBXXX RVQ ZAY WQAGE QFZQ OL JVZFKOYIIAIX."}, "tools": ["factor 3233", "calc (53-1)*(61-1)", "modinv 17 <phi>", "rsa-decrypt <d> 3233 $SESSION_KEY", "vigenere-decrypt <key> $MESSAGE"], "outro": "PERSEVERANCE. From Caesar to RSA, every cipher has fallen to a clever mind. The timeline is restored, Agent. The Archive Division salutes you."}'::jsonb,
  array['Historical Cryptography', 'Asymmetric Cryptography', 'Symmetric Cryptography', 'Modular Arithmetic']::text[], true, 5, 250
from public.storylines s where s.slug = 'puzzles-of-the-past'
on conflict (slug) do update set
  storyline_id = excluded.storyline_id, title = excluded.title, description = excluded.description,
  story_segment = excluded.story_segment, challenge_prompt = excluded.challenge_prompt,
  cipher_type = excluded.cipher_type, payload = excluded.payload, skills = excluded.skills,
  is_boss = excluded.is_boss, order_index = excluded.order_index, xp_reward = excluded.xp_reward;

insert into public.lab_solutions (lab_id, solution, hints)
select id, 'PERSEVERANCE', '["`factor 3233` gives 53 × 61. Then φ(n) = 52 × 60 = 3120 (`calc (53-1)*(61-1)`).", "d = `modinv 17 3120` = 2753. Run `rsa-decrypt 2753 3233 $SESSION_KEY` to get the session key.", "The session key is TURING. Run `vigenere-decrypt TURING $MESSAGE`."]'::jsonb from public.labs where slug = 'digital-age-decryption'
on conflict (lab_id) do update set solution = excluded.solution, hints = excluded.hints;

